{
  "title": "Discussion on taxes, domain purchase, and app idea",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing complications",
      "claims": [
        {
          "text": "User P1 paid about 1000 UAH after re‑filing taxes with help from aunt Sveta, avoiding larger fines.",
          "evidence": [1]
        },
        {
          "text": "The tax filing process can take about an hour with Excel, performed once a day.",
          "evidence": [5, 6]
        },
        {
          "text": "Quarterly reports must be filed correctly and on time.",
          "evidence": [7]
        },
        {
          "text": "Missing or mis‑labelled columns in declarations cause major headaches.",
          "evidence": [8]
        },
        {
          "text": "The calculator mentioned works only with a UAH‑based FOP; currency conversion must be done per transaction date.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase discussion",
      "claims": [
        {
          "text": "User P2 claimed they have not even bought a domain.",
          "evidence": [2]
        },
        {
          "text": "P1 suggested buying a calculator first, then they'll have money for a domain.",
          "evidence": [4]
        },
        {
          "text": "User P4 expressed doubt about spending money on a domain.",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Viability of a cross‑platform app",
      "claims": [
        {
          "text": "P1 researched earning potential and listed many drawbacks of a web‑only product (low SEO, no external traffic, harsh paywall, near‑zero conversion).",
          "evidence": [11]
        },
        {
          "text": "A successful approach mentioned includes fast delivery (< 1 week), a cross‑platform stack (Flutter), and copying popular ideas with minor enhancements.",
          "evidence": [12]
        },
        {
          "text": "P4 questioned whether the discussion referred to Igor's attempt to earn money.",
          "evidence": [13, 14]
        },
        {
          "text": "P1 doubts the app can generate sales, estimating a low chance of monthly purchases.",
          "evidence": [17]
        },
        {
          "text": "P1 notes LinkedIn audience composition has shifted, with technical/managerial posts now under 50 %.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "source-code-password",
      "title": "Access to app source code / password",
      "claims": [
        {
          "text": "P4 mentioned the app’s password is stored in local storage as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "P1 asked if the source code could be found via password search.",
          "evidence": [21]
        },
        {
          "text": "P4 sarcastically replied they didn’t pay 299 UAH for it.",
          "evidence": [22]
        },
        {
          "text": "P4 indicated the password is bundled inside the app.",
          "evidence": [23]
        },
        {
          "text": "P5 labeled the app as pirateware.",
          "evidence": [24]
        }
      ]
    },
    {
      "id": "scam-accusations",
      "title": "Accusations of scam / low value",
      "claims": [
        {
          "text": "P4 mocked the project as a free “vibe‑code” with low value and suggested it’s a scam.",
          "evidence": [30, 32]
        },
        {
          "text": "P5 affirmed the scam claim.",
          "evidence": [33, 34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Will anyone actually purchase the domain discussed?",
      "evidence": [9, 10]
    },
    {
      "text": "Is there a sufficient user base willing to pay 299 UAH for the app?",
      "evidence": [20, 21]
    }
  ]
}
